import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ProximityMarketingMapProps = Record<string, any>;

const Arrow: React.FC<{
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  color: string;
  progress: number;
  startOffset: number;
  endOffset: number;
}> = ({ x1, y1, x2, y2, color, progress, startOffset, endOffset }) => {
  const angle = Math.atan2(y2 - y1, x2 - x1);
  const length = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
  
  // Calculate actual start and end points based on circle radii
  const actualStart = startOffset;
  const actualEnd = length - endOffset;
  
  // Current length based on animation progress
  const currentLength = interpolate(progress, [0, 1], [0, actualEnd - actualStart]);
  
  if (currentLength <= 0) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: x1,
        top: y1,
        width: length,
        height: 0,
        transform: `rotate(${angle}rad)`,
        transformOrigin: "0 0",
        pointerEvents: "none",
      }}
    >
      {/* Arrow Line */}
      <div
        style={{
          position: "absolute",
          left: actualStart,
          top: -1.5, // Center the line (stroke width 3)
          width: currentLength,
          height: 3,
          backgroundColor: color,
        }}
      />
      
      {/* Arrow Head */}
      <div
        style={{
          position: "absolute",
          left: actualStart + currentLength,
          top: -6,
          width: 0,
          height: 0,
          borderLeft: `10px solid ${color}`,
          borderTop: "6px solid transparent",
          borderBottom: "6px solid transparent",
          opacity: progress > 0.1 ? 1 : 0, // Prevent artifact at start
        }}
      />
    </div>
  );
};

const ProximityMarketingMap: React.FC<ProximityMarketingMapProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  centralColor = "#ff7f00", // Orange from image
  nodeColor = "#0ea5e9", // Sky blue from image
  centralText = "Proximity-Based Marketing",
  centralTextColor = "#000000",
  nodeTextColor = "#ffffff",
  arrowColor = "#0ea5e9",
  nodeRadius = 75,
  centerRadius = 70,
  diagramRadius = 380,
  items = [
    "Retail",
    "Hotels",
    "Food",
    "Beverage",
    "Hobbies",
    "Car parks",
    "Tourism",
    "WiFi spots",
    "Loyalty cards",
    "Public\ntransport",
  ],
}) => {
  useFontLoader(["Inter", "Roboto"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const cx = width / 2;
  const cy = height / 2;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate dynamic size for central circle to fit text
  const baseFontSize = centerRadius * 0.22;
  const lines = centralText.split('\n');
  const maxLineLength = Math.max(...lines.map(l => l.length));
  
  // Heuristic 1: Ensure width fits (approx 0.45 factor for char width + padding)
  const minRadiusByWidth = maxLineLength * baseFontSize * 0.45;
  
  // Heuristic 2: Ensure area fits (for wrapping/dense text)
  // Factor 0.8 * sqrt(length) approximates safe area radius
  const minRadiusByArea = baseFontSize * 0.8 * Math.sqrt(centralText.length);
  
  // Use the largest requirement, but never go below the user's setting
  const actualCenterRadius = Math.max(centerRadius, minRadiusByWidth, minRadiusByArea);

  // Animation Timing
  const centerEntrance = spring({
    frame,
    fps,
    config: { damping: 12 },
  });

  const arrowStartFrame = 15;
  const nodesStartFrame = 30;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* Central Node */}
      <div
        style={{
          position: "absolute",
          left: cx - actualCenterRadius,
          top: cy - actualCenterRadius,
          width: actualCenterRadius * 2,
          height: actualCenterRadius * 2,
          borderRadius: "50%",
          backgroundColor: centralColor,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
          boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)",
          transform: `scale(${centerEntrance})`,
        }}
      >
        <div
          style={{
            color: centralTextColor,
            fontWeight: 700,
            fontSize: baseFontSize, // Use base size so text doesn't scale up with the fix
            textAlign: "center",
            lineHeight: 1.2,
            whiteSpace: "pre-wrap",
            opacity: interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" }),
          }}
        >
          {centralText}
        </div>
      </div>

      {/* Surrounding Nodes & Arrows */}
      {items.map((item, index) => {
        const angleStep = (2 * Math.PI) / items.length;
        // Start from -PI/2 (Top) and go clockwise
        const angle = -Math.PI / 2 + index * angleStep; 
        
        const nodeX = cx + diagramRadius * Math.cos(angle);
        const nodeY = cy + diagramRadius * Math.sin(angle);

        // Arrow Animation
        const arrowProgress = interpolate(
          frame,
          [arrowStartFrame, arrowStartFrame + 15],
          [0, 1],
          { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
        );

        // Node Pop Animation (Staggered)
        const nodeDelay = nodesStartFrame + index * 2;
        const nodeScale = spring({
          frame: frame - nodeDelay,
          fps,
          config: { stiffness: 100, damping: 10 },
        });

        // Text Fade
        const textOpacity = interpolate(
          frame,
          [nodeDelay + 5, nodeDelay + 15],
          [0, 1],
          { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
        );

        return (
          <React.Fragment key={index}>
            {/* Arrow Layer */}
            <Arrow
              x1={cx}
              y1={cy}
              x2={nodeX}
              y2={nodeY}
              color={arrowColor}
              progress={arrowProgress}
              startOffset={actualCenterRadius + 5} // Gap from actual center radius
              endOffset={nodeRadius + 5} // Gap from node
            />

            {/* Node Layer */}
            <div
              style={{
                position: "absolute",
                left: nodeX - nodeRadius,
                top: nodeY - nodeRadius,
                width: nodeRadius * 2,
                height: nodeRadius * 2,
                borderRadius: "50%",
                backgroundColor: nodeColor,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                zIndex: 5,
                transform: `scale(${nodeScale})`,
                boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1)",
              }}
            >
              <div
                style={{
                  color: nodeTextColor,
                  fontWeight: 600,
                  fontSize: nodeRadius * 0.25,
                  textAlign: "center",
                  lineHeight: 1.1,
                  whiteSpace: "pre-wrap",
                  opacity: textOpacity,
                  maxWidth: "90%",
                }}
              >
                {item}
              </div>
            </div>
          </React.Fragment>
        );
      })}
    </AbsoluteFill>
  );
};

export default ProximityMarketingMap;